import{_ as i,o as s,c as e,a2 as a}from"./chunks/framework.vLhlLNVn.js";const g=JSON.parse('{"title":"LLM & Autonomous Agent Integration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/llm-integration.md","filePath":"guide/llm-integration.md","lastUpdated":null}'),n={name:"guide/llm-integration.md"};function l(o,t,h,p,r,d){return s(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="llm-autonomous-agent-integration" tabindex="-1">LLM &amp; Autonomous Agent Integration <a class="header-anchor" href="#llm-autonomous-agent-integration" aria-label="Permalink to &quot;LLM &amp; Autonomous Agent Integration&quot;">​</a></h1><p>Myelin is built specifically to bridge Large Language Models with systems-level execution.</p><h2 id="the-llm-diagnostic-protocol-llm" tabindex="-1">The LLM Diagnostic Protocol (<code>--llm</code>) <a class="header-anchor" href="#the-llm-diagnostic-protocol-llm" aria-label="Permalink to &quot;The LLM Diagnostic Protocol (`--llm`)&quot;">​</a></h2><p>Traditional compilers emit multi-line ASCII art and lengthy explanations designed for human eyes:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error[E0308]: mismatched types</span></span>\n<span class="line"><span>  --&gt; src/main.rs:12:18</span></span>\n<span class="line"><span>   |</span></span>\n<span class="line"><span>12 |     let x: i32 = &quot;hello&quot;;</span></span>\n<span class="line"><span>   |            ---   ^^^^^^^ expected `i32`, found `&amp;str`</span></span>\n<span class="line"><span>   |            |</span></span>\n<span class="line"><span>   |            expected due to this</span></span></code></pre></div><p>While human-friendly, feeding this back to an LLM:</p><ol><li>Burns dozens of precious context tokens.</li><li>Increases autoregressive latency.</li><li>Requires the LLM to deduce the exact column and repair step.</li></ol><h3 id="myelin-single-line-wire-format" tabindex="-1">Myelin Single-Line Wire Format <a class="header-anchor" href="#myelin-single-line-wire-format" aria-label="Permalink to &quot;Myelin Single-Line Wire Format&quot;">​</a></h3><p>In Myelin, running with <code>--llm</code> formats every error, warning, and note into a deterministic <strong>single-line wire format</strong>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;SEVERITY&gt; &lt;CODE&gt; &lt;FILE&gt;:&lt;LINE&gt;:&lt;COL&gt; | &lt;KIND&gt; &lt;DETAIL&gt; | fix: &lt;REPAIR_HINT&gt;</span></span></code></pre></div><h3 id="real-compiler-output-examples" tabindex="-1">Real Compiler Output Examples <a class="header-anchor" href="#real-compiler-output-examples" aria-label="Permalink to &quot;Real Compiler Output Examples&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ERR E001 math.myl:5:1 | tab_indent | fix: replace tabs with 2-space multiples</span></span>\n<span class="line"><span>ERR E002 ledger.myl:14:3 | odd_indent spaces=3 | fix: align statement to 2 or 4 spaces</span></span>\n<span class="line"><span>ERR E008 server.myl:18:7 | missing_capability cap=!net | fix: add !net to &#39;#fn main&#39; signature</span></span></code></pre></div><p>An autonomous agent can parse this with a single regex:</p><div class="language-regex vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">regex</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">^(</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">?P&lt;sev&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">ERR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">WARN</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">)</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> (</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">?P&lt;code&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">E</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">)</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> (</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">?P&lt;file&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">^</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:]</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">(</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">?P&lt;line&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">(</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">?P&lt;col&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">)</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> (</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">?P&lt;detail&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">^</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">|]</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">)</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\|</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;"> fix: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">(</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">?P&lt;fix&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">)$</span></span></code></pre></div><p>The agent applies the fix in its next code revision with 0 wasted reasoning steps.</p><hr><h2 id="the-900-token-llm-skill-file-skill-md" tabindex="-1">The 900-Token LLM Skill File (<code>SKILL.md</code>) <a class="header-anchor" href="#the-900-token-llm-skill-file-skill-md" aria-label="Permalink to &quot;The 900-Token LLM Skill File (`SKILL.md`)&quot;">​</a></h2><p>Rather than requiring an agent to read a 500-page language specification, Myelin provides <a href="https://github.com/can/ailang/blob/main/SKILL.md" target="_blank" rel="noreferrer"><code>SKILL.md</code></a> in the root repository.</p><h3 id="how-to-use-with-ai-agents" tabindex="-1">How to Use with AI Agents <a class="header-anchor" href="#how-to-use-with-ai-agents" aria-label="Permalink to &quot;How to Use with AI Agents&quot;">​</a></h3><p>When instructing Claude, ChatGPT, or Gemini to write Myelin code:</p><ol><li>Provide the content of <code>SKILL.md</code> as system instructions or prompt context (~900 tokens).</li><li>The model will reliably emit canonical, valid <code>.myl</code> files.</li><li>Hook compiler verification into the agent execution loop:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myelinc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generated.myl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --llm</span></span></code></pre></div></li><li>If output is non-empty, provide the single-line error directly back to the agent for instantaneous repair.</li></ol><hr><h2 id="token-efficiency-benchmark" tabindex="-1">Token Efficiency Benchmark <a class="header-anchor" href="#token-efficiency-benchmark" aria-label="Permalink to &quot;Token Efficiency Benchmark&quot;">​</a></h2><p>Writing equivalent logic across different programming languages demonstrates Myelin&#39;s dramatic token savings:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Language</th><th style="text-align:left;">Typical Token Count (o200k)</th><th style="text-align:left;">Boilerplate / Ceremony</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Java</strong></td><td style="text-align:left;">240 tokens</td><td style="text-align:left;">Classes, packages, types, braces, exceptions</td></tr><tr><td style="text-align:left;"><strong>TypeScript</strong></td><td style="text-align:left;">185 tokens</td><td style="text-align:left;">Type annotations, import/export, braces, async/await</td></tr><tr><td style="text-align:left;"><strong>Rust</strong></td><td style="text-align:left;">170 tokens</td><td style="text-align:left;">Lifetime parameters, Result match, braces, use</td></tr><tr><td style="text-align:left;"><strong>Python</strong></td><td style="text-align:left;">130 tokens</td><td style="text-align:left;">Indentation, def, colons, import, type hints</td></tr><tr><td style="text-align:left;"><strong>Myelin (<code>.myl</code>)</strong></td><td style="text-align:left;"><strong>68 tokens</strong></td><td style="text-align:left;"><strong>55% - 70% reduction in tokens emitted!</strong></td></tr></tbody></table>',25)])])}const c=i(n,[["render",l]]);export{g as __pageData,c as default};
